import{_ as c,l,o as t,c as o,v as a,p as i,x as n,d as s,i as T,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"netfilter 与 conntrack","description":"","frontmatter":{"title":"netfilter 与 conntrack","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/netfilter-conntrack.md","filePath":"cs/netfilter-conntrack.md","lastUpdated":1789023840000}'),f={name:"cs/netfilter-conntrack.md"};function d(h,e,k,_,P,A){const r=l("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="netfilter-与-conntrack" tabindex="-1">netfilter 与 conntrack <a class="header-anchor" href="#netfilter-与-conntrack" aria-label="Permalink to &quot;netfilter 与 conntrack&quot;">​</a></h1><div class="epigraph"><p>netfilter 在包路径上设钩子；conntrack 把同一连接的各方向报文收成一项状态，NAT 与状态防火墙靠它。</p><footer>—— 据 Russel, Linux netfilter Hacking HOWTO；Linux nf_conntrack 文档</footer></div><p><a href="/cs/rx-path">RX</a>/<a href="/cs/tx-path-qdisc">TX</a> 已经点名钩子。<a href="/cs/kernel-tcp-impl">TCP</a> 有自己的状态，那是传输对端。防火墙需要 <strong>另一份</strong> 连接表。缺口是 netfilter 钩子位置与 conntrack 元组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PREROUTING、INPUT、FORWARD、OUTPUT、POSTROUTING 五类钩。iptables/nftables 在钩上匹配、丢、改、跳 NAT。无状态规则不能「只允许已建立」。conntrack：五元组 + 状态（NEW/ESTABLISHED/RELATED），ICMP 差错可 RELATED。缺口：表满则 drop（DoS）；NAT 改地址必须改校验与端口；与 <a href="/cs/socket-buffers">套接字</a> 查找用的是改后或改前地址，取决于钩点。本课不把 nft 语法写成手册。</p><p><span class="marginnote">nf_conn 可被 helper 解析 FTP 等。关闭 conntrack 对转发性能有好处，但 NAT 不能关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入包：PREROUTING 做 DNAT，路由，再 INPUT 或 FORWARD。出包：OUTPUT、POSTROUTING SNAT。对照 TCP 状态机：conntrack 不重传，只跟踪看见过的方向。对照 <a href="/cs/dm-crypt">dm-crypt</a>：一个改块，一个改包头。对照 LSM：netfilter 不是 inode 标签。</p>',8)),(t(),i(p,null,{default:n(()=>[T(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%8C%85%22%5D%20--%3E%20PRE%5B%22PREROUTING%22%5D%0A%20%20PRE%20--%3E%20CT%5B%22conntrack%22%5D%0A%20%20CT%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%22%5D%0A%20%20RT%20--%3E%20INP%5B%22INPUT%20%E6%88%96%20FORWARD%22%5D%0A%20%20OUT%5B%22%E6%9C%AC%E6%9C%BA%E5%8F%91%E5%87%BA%22%5D%20--%3E%20POST%5B%22POSTROUTING%20NAT%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>netfilter 把「包策略」收成可编程钩，使 NAT 与防火墙成为 OS 功能而非旁路盒子。conntrack 是有状态的代价：内存与锁。不要写成安全产品对比文。与 <a href="/cs/namespaces">namespaces</a>：每 netns 一份 conntrack，容器隔离靠后课 netns。</p><p>连接跟踪与应用层代理不同：它不终结 TCP，只改或放行。</p><p>实现上：表满时 NEW 包被丢，表现为随机连不上。helper 解析载荷会放大 CPU，也是攻击面。flowtable 把已确认转发路径短路到更早的交换，绕过多次钩子。 读法上只引用<a href="/cs/kernel-tcp-impl">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>netfilter 与 conntrack</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 flowtable 硬件卸载的全部。不保证 conntrack 对所有隧道内层可见。下一课把整份栈复制一份：网络命名空间与 veth。</p><p>版本字段会变，课序钉的是机制对象「netfilter 与 conntrack」，不是某一主线内核的结构体名。 后课默认：钩子可过滤/NAT，conntrack 记连接。每容器一份协议栈如何用 veth 接起来，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>netfilter 钩在收发与转发路径上。</li><li>conntrack 用元组做有状态放行与 NAT。</li><li>netns 与 veth 是下一课。</li><li>出处：netfilter HOWTO；Linux nf_conntrack；Benvenuti。</li></ul>',11))])}const m=c(f,[["render",d]]);export{E as __pageData,m as default};
